<?php
/**
 * Contenu de démonstration · Les Nuits du Quai (festival fictif).
 *
 * Exécuté par la recette Playground (blueprint.json) juste après l'installation de WordPress.
 * En séance 4, le vrai site aura son propre contenu, saisi dans l'administration.
 * Les visuels des artistes sont des images abstraites générées pour le cours.
 */

// Le script tourne sans utilisateur connecté : on garde les images intégrées au contenu.
kses_remove_filters();

function nq_page( $title, $content, $order = 0 ) {
	return wp_insert_post( array(
		'post_type'    => 'page',
		'post_status'  => 'publish',
		'post_title'   => $title,
		'post_content' => $content,
		'menu_order'   => $order,
	) );
}

$visuels = array(
	'Brume' => '',
	'Les Marées Basses' => '',
	'Docks Électriques' => '',
	'Nora Vey' => '',
	'Lumen Collectif' => '',
	'Sœurs Halogènes' => '',
	'Fanfare du Port' => '',
	'Les Lucioles' => '',
	'Grand Ressac' => ''
);

$soirs = array(
	array( 'Vendredi 26 juin', array( array( '19 h 30', 'Brume' ), array( '21 h', 'Les Marées Basses' ), array( '23 h', 'Docks Électriques' ) ) ),
	array( 'Samedi 27 juin', array( array( '19 h 30', 'Nora Vey' ), array( '21 h', 'Lumen Collectif' ), array( '23 h', 'Sœurs Halogènes' ) ) ),
	array( 'Dimanche 28 juin', array( array( '18 h', 'Fanfare du Port' ), array( '20 h', 'Les Lucioles' ), array( '22 h', 'Grand Ressac' ) ) ),
);

// Le programme : une colonne par soir, les horaires, puis un bouton « Réserver ».
$colonnes = '';
foreach ( $soirs as $soir ) {
	$items = '';
	foreach ( $soir[1] as $concert ) {
		$items .= '<!-- wp:list-item --><li><span class="horaire">' . esc_html( $concert[0] ) . '</span> · ' . esc_html( $concert[1] ) . '</li><!-- /wp:list-item -->';
	}
	$colonnes .= '<!-- wp:column --><div class="wp-block-column">'
		. '<!-- wp:heading {"level":3} --><h3 class="wp-block-heading">' . esc_html( $soir[0] ) . '</h3><!-- /wp:heading -->'
		. '<!-- wp:list --><ul class="wp-block-list">' . $items . '</ul><!-- /wp:list -->'
		. '<!-- wp:buttons {"className":"boutons-programme"} --><div class="wp-block-buttons boutons-programme"><!-- wp:button --><div class="wp-block-button"><a class="wp-block-button__link wp-element-button" href="#billetterie">Réserver</a></div><!-- /wp:button --></div><!-- /wp:buttons -->'
		. '</div><!-- /wp:column -->';
}
$programme = '<!-- wp:columns {"className":"programme"} --><div class="wp-block-columns programme">' . $colonnes . '</div><!-- /wp:columns -->';

// Accueil.
$accueil = '<!-- wp:heading {"level":1} --><h1 class="wp-block-heading">Trois soirs au bord de l’eau</h1><!-- /wp:heading -->'
	. '<!-- wp:paragraph --><p>Concerts et installations visuelles en plein air, du 26 au 28 juin. Festival fictif, imaginé pour le cours Vibe coding et collaboration.</p><!-- /wp:paragraph -->'
	. '<!-- wp:buttons --><div class="wp-block-buttons"><!-- wp:button {"className":"billetterie"} --><div class="wp-block-button billetterie"><a class="wp-block-button__link wp-element-button" href="#billetterie">Billetterie</a></div><!-- /wp:button --><!-- wp:button {"className":"is-style-outline"} --><div class="wp-block-button is-style-outline"><a class="wp-block-button__link wp-element-button" href="#programme">Voir le programme</a></div><!-- /wp:button --></div><!-- /wp:buttons -->'
	. '<!-- wp:heading {"anchor":"programme"} --><h2 class="wp-block-heading" id="programme">Programme</h2><!-- /wp:heading -->'
	. $programme
	. '<!-- wp:heading {"anchor":"billetterie"} --><h2 class="wp-block-heading" id="billetterie">Billetterie</h2><!-- /wp:heading -->'
	. '<!-- wp:paragraph --><p>Pass un soir : 12 €. Pass trois soirs : 30 €. Gratuit pour les moins de 12 ans. (Festival fictif : rien n’est en vente.)</p><!-- /wp:paragraph -->';

// Artistes : une carte par artiste, avec son visuel.
$cartes = '';
foreach ( $soirs as $soir ) {
	foreach ( $soir[1] as $concert ) {
		$nom     = $concert[1];
		$cartes .= '<!-- wp:group {"className":"carte-artiste","layout":{"type":"default"}} --><div class="wp-block-group carte-artiste">'
			. '<!-- wp:image --><figure class="wp-block-image"><img src="data:image/jpeg;base64,' . $visuels[ $nom ] . '" alt="Visuel de ' . esc_attr( $nom ) . '"/></figure><!-- /wp:image -->'
			. '<!-- wp:heading {"level":3} --><h3 class="wp-block-heading">' . esc_html( $nom ) . '</h3><!-- /wp:heading -->'
			. '<!-- wp:paragraph --><p>' . esc_html( $soir[0] . ' · ' . $concert[0] ) . '</p><!-- /wp:paragraph -->'
			. '</div><!-- /wp:group -->';
	}
}
$artistes = '<!-- wp:paragraph --><p>Neuf artistes et collectifs, sur trois soirs.</p><!-- /wp:paragraph -->'
	. '<!-- wp:group {"layout":{"type":"grid","minimumColumnWidth":"12rem"}} --><div class="wp-block-group">' . $cartes . '</div><!-- /wp:group -->';

// Infos pratiques.
$infos = '<!-- wp:heading --><h2 class="wp-block-heading">Venir</h2><!-- /wp:heading -->'
	. '<!-- wp:paragraph --><p>En tram, ligne 1, arrêt Quai, puis 3 minutes à pied le long de l’eau. Parking vélo gardé à l’entrée.</p><!-- /wp:paragraph -->'
	. '<!-- wp:heading --><h2 class="wp-block-heading">Horaires</h2><!-- /wp:heading -->'
	. '<!-- wp:paragraph --><p>Ouverture des portes à 18 h, dernier concert vers 23 h.</p><!-- /wp:paragraph -->'
	. '<!-- wp:heading --><h2 class="wp-block-heading">Accessibilité</h2><!-- /wp:heading -->'
	. '<!-- wp:paragraph --><p>Le site est accessible en fauteuil roulant. Une plateforme près de la scène est réservée aux personnes à mobilité réduite.</p><!-- /wp:paragraph -->';

$accueil_id = nq_page( 'Accueil', $accueil, 0 );
update_post_meta( $accueil_id, '_wp_page_template', 'page-no-title' );
nq_page( 'Programme', $programme, 1 );
nq_page( 'Artistes', $artistes, 2 );
nq_page( 'Infos pratiques', $infos, 3 );

update_option( 'show_on_front', 'page' );
update_option( 'page_on_front', $accueil_id );
update_option( 'blogname', 'Les Nuits du Quai' );
update_option( 'blogdescription', 'Festival fictif · fin juin, au bord de l’eau' );

// Retire la page et l'article d'exemple de WordPress, et la page de confidentialité.
foreach ( get_posts( array( 'post_type' => array( 'post', 'page' ), 'post_status' => 'any', 'numberposts' => -1 ) ) as $p ) {
	if ( (int) $p->ID !== (int) $accueil_id && ! in_array( $p->post_title, array( 'Accueil', 'Programme', 'Artistes', 'Infos pratiques' ), true ) ) {
		wp_delete_post( $p->ID, true );
	}
}
